    // push rising edge: add item if not full
    IF pushEn AND NOT prevPush THEN
        IF count < 8 THEN
            count := count + 1;
            fifo[count] := pushItem;
        END_IF
    END_IF

    // outputs
    full  := (count = 8);
    empty := (count = 0);
    head  := 0;
    IF NOT empty THEN
        head := fifo[1];
    END_IF

    // update edge detection history
    prevPush := pushEn;
    prevPop  := popEn;
